var countPairs = function(deliciousness) {
    const MOD = 1000000007;
    const freq = new Map();
    const powers = [];
    for (let i = 0; i < 22; ++i) powers.push(1 << i);

    let ans = 0;
    for (const x of deliciousness) {
        for (const p of powers) {
            const target = p - x;
            if (freq.has(target)) {
                ans = (ans + freq.get(target)) % MOD;
            }
        }
        freq.set(x, (freq.get(x) || 0) + 1);
    }
    return ans;
};
